import React, { useEffect } from 'react';
import AnimatedBackground from '../components/AnimatedBackground.jsx';
import HexagonPulseBackground from '../components/HexagonPulseBackground';
import { Link } from 'react-router-dom';
import img1 from '../assets/highlight1.png';
import img2 from '../assets/highlight2.png';
import img3 from '../assets/highlight3.png';
import img4 from '../assets/highlight4.png';
import img5 from '../assets/highlight5.png';

export default function KidsDentistry() {
  useEffect(() => {
    document.title = "🦷 Kids Dentistry – Expert Pediatric Dental Care | Urja Dental Clinic";
    
    const io = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) entry.target.classList.add('is-visible');
      });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);

  return (
    <div className="relative min-h-screen bg-white overflow-x-hidden">
      <div className="absolute inset-0 -z-30 opacity-95 pointer-events-none" aria-hidden>
        <AnimatedBackground />
      </div>
      <div className="absolute inset-0 -z-20 pointer-events-none" aria-hidden>
        <HexagonPulseBackground />
      </div>

      <header className="relative max-w-6xl mx-auto px-6 py-20 text-center">
        <div className="relative inline-block w-full bg-white/80 backdrop-blur-md rounded-3xl px-8 py-8 shadow-2xl overflow-visible">
          <h1 className="text-3xl md:text-4xl font-extrabold text-sky-800 mb-3">Kids Dentistry — Gentle Care for Little Smiles</h1>
          <p className="text-gray-700 max-w-3xl mx-auto mb-6">We make dental visits friendly, fun, and educational. Our pediatric dentistry approach focuses on prevention, gentle behavior guidance, and treatments tailored to growing mouths so children develop healthy habits and a positive attitude toward oral care.</p>

          <div className="flex justify-center gap-4 mb-6">
            <Link to="/book-online" className="inline-block">
              <button className="px-6 py-2 rounded-full bg-rose-500 text-white font-semibold shadow hover:scale-105 transition">Book a Child Check</button>
            </Link>
            <a href="#gallery" className="px-6 py-2 rounded-full border border-rose-500 text-rose-500 font-semibold hover:bg-rose-50 transition">See Fun Cases</a>
          </div>

          {/* playful balloon accents (SVG) */}
          <div className="mt-4 flex justify-center pointer-events-none aria-hidden">
            <svg width="360" height="140" viewBox="0 0 360 140" xmlns="http://www.w3.org/2000/svg" aria-hidden>
              <g className="balloon-group">
                <ellipse className="balloon b1" cx="40" cy="90" rx="20" ry="28" fill="#ff8dab" />
                <ellipse className="balloon b2" cx="120" cy="70" rx="18" ry="24" fill="#60a5fa" />
                <ellipse className="balloon b3" cx="220" cy="60" rx="22" ry="30" fill="#facc15" />
                <ellipse className="balloon b4" cx="300" cy="80" rx="16" ry="22" fill="#7c3aed" />
                <path className="string s1" d="M40 118 L40 140" stroke="#cc6b8b" strokeWidth="1.6" strokeLinecap="round" />
                <path className="string s2" d="M120 98 L120 140" stroke="#2b6cb0" strokeWidth="1.6" strokeLinecap="round" />
                <path className="string s3" d="M220 90 L220 140" stroke="#d4af37" strokeWidth="1.6" strokeLinecap="round" />
                <path className="string s4" d="M300 118 L300 140" stroke="#5126c7" strokeWidth="1.6" strokeLinecap="round" />
              </g>
            </svg>
          </div>
        </div>
      </header>
  <div className="relative min-h-screen bg-white overflow-x-hidden">
          <div className="absolute inset-0 -z-30 opacity-95 pointer-events-none" aria-hidden>
            <AnimatedBackground />
          </div>
          <div className="absolute inset-0 -z-20 pointer-events-none" aria-hidden>
            <HexagonPulseBackground />
          </div>

          <header className="relative max-w-6xl mx-auto px-6 py-20 text-center">
            <div className="relative inline-block w-full bg-white/80 backdrop-blur-md rounded-3xl px-8 py-8 shadow-2xl overflow-visible">
              <h1 className="text-3xl md:text-4xl font-extrabold text-sky-800 mb-3">Kids Dentistry — Gentle Care for Little Smiles</h1>
              <p className="text-gray-700 max-w-3xl mx-auto mb-6">We make dental visits friendly, fun, and educational. Our pediatric dentistry approach focuses on prevention, gentle behavior guidance, and treatments tailored to growing mouths so children develop healthy habits and a positive attitude toward oral care.</p>

              <div className="flex justify-center gap-4 mb-6">
                                <a href="#gallery" className="px-6 py-2 rounded-full border border-rose-500 text-rose-500 font-semibold hover:bg-rose-50 transition">See Fun Cases</a>
              </div>

              {/* playful balloon accents (SVG) */}
              <div className="mt-4 flex justify-center pointer-events-none aria-hidden">
                <svg width="360" height="140" viewBox="0 0 360 140" xmlns="http://www.w3.org/2000/svg" aria-hidden>
                  <g className="balloon-group">
                    <ellipse className="balloon b1" cx="40" cy="90" rx="20" ry="28" fill="#ff8dab" />
                    <ellipse className="balloon b2" cx="120" cy="70" rx="18" ry="24" fill="#60a5fa" />
                    <ellipse className="balloon b3" cx="220" cy="60" rx="22" ry="30" fill="#facc15" />
                    <ellipse className="balloon b4" cx="300" cy="80" rx="16" ry="22" fill="#7c3aed" />
                    <path className="string s1" d="M40 118 L40 140" stroke="#cc6b8b" strokeWidth="1.6" strokeLinecap="round" />
                    <path className="string s2" d="M120 98 L120 140" stroke="#2b6cb0" strokeWidth="1.6" strokeLinecap="round" />
                    <path className="string s3" d="M220 90 L220 140" stroke="#d4af37" strokeWidth="1.6" strokeLinecap="round" />
                    <path className="string s4" d="M300 118 L300 140" stroke="#5126c7" strokeWidth="1.6" strokeLinecap="round" />
                  </g>
                </svg>
              </div>
            </div>
          </header>

          <section id="gallery" className="max-w-6xl mx-auto px-6 py-12">
            <h2 className="text-2xl md:text-3xl font-bold text-sky-800 mb-6 text-center reveal">Happy Smiles Gallery</h2>
            <div className="flex flex-wrap gap-6 justify-center items-stretch">
              {[img1, img2, img3, img4, img5].map((src, idx) => (
                <figure key={idx} className={`reveal shadow-xl transform transition hover:scale-105 rounded-3xl overflow-hidden bg-gradient-to-tr from-white via-pink-100 to-sky-100 flex flex-col ${idx % 2 === 0 ? 'w-full sm:w-2/3 md:w-1/2' : 'w-full sm:w-1/3 md:w-1/4'}`} style={{ ['--delay']: `${idx * 100}ms` }}>
                  <div className="relative w-full h-56 flex items-center justify-center">
                    <img src={src} alt={`kids-case-${idx+1}`} className="w-full h-full object-cover rounded-3xl scale-105" />
                    <div className="absolute top-2 left-2 bg-white/80 rounded-full px-3 py-1 text-xs font-bold text-rose-500 shadow">Smile {idx + 1}</div>
                  </div>
                  <figcaption className="p-4 bg-white/80 backdrop-blur-md flex-1 flex items-center justify-center">
                    <p className="text-sm text-gray-700 font-semibold text-center">Playful, positive appointments with preventive focus.</p>
                  </figcaption>
                </figure>
              ))}
            </div>
          </section>

          <section className="w-full px-6 md:px-12 py-12 bg-white">
            <div className="max-w-screen-xl mx-auto">
              <h3 className="text-2xl md:text-3xl font-bold text-sky-800 mb-6 text-center reveal">Pediatric Dental Care – What Parents Should Know</h3>
              <div className="reveal mt-8">
                <p className="mb-4">Our team uses behavior guidance techniques tailored to each child’s temperament. We explain procedures in child-friendly language, allow a parent to be present, and use distraction and positive reinforcement to create a calm environment. For necessary treatments — fillings, sealants, or minor extractions — we prioritize conservative methods and local anaesthesia when needed. When a child requires more extensive care, we discuss options including conscious sedation or treatment under general anaesthesia, always prioritizing safety and the least invasive option that achieves a predictable result.</p>
                <p className="mb-4">Preventive care is the cornerstone of pediatric dentistry. Dental sealants protect deep grooves on molars from decay, topical fluoride strengthens enamel, and nutritional counseling helps parents reduce cariogenic exposures. We also screen for early orthodontic issues; interceptive measures can simplify later treatment and support normal jaw growth. For children with dental anxiety or special needs, we create individualized care plans that include longer visits and sensory-friendly adjustments.</p>
                <p className="mb-4">A child's restored smile affects more than health — it supports speech development, nutrition, and self-esteem. We partner with parents to establish effective habits: gentle brushing with age-appropriate fluoride toothpaste, regular check-ups, and limiting sugary snacks and prolonged bottle use. Our goal is to make each visit a positive experience that builds confidence and resilience so kids grow into adults who maintain excellent oral health.</p>
                <p>If you have questions about teething, thumb-sucking, or how to prepare your child for a dental visit, book a consultation. We’ll discuss personalized strategies and create a safe, friendly pathway for your child's dental journey.</p>
              </div>
            </div>
          </section>

        <style>{`
      .reveal { opacity: 0; transform: translateY(28px) scale(0.995); will-change: transform, opacity; }
      .reveal.is-visible { animation: revealIn 700ms cubic-bezier(.22,.9,.36,1) both; }
      @keyframes revealIn { from { opacity: 0; transform: translateY(28px) scale(0.995); } to { opacity: 1; transform: translateY(0) scale(1); } }
      .reveal { animation-delay: var(--delay, 0ms); }

      /* balloon float animations */
      .balloon { transform-origin: center; opacity: 0.95; filter: drop-shadow(0 8px 18px rgba(0,0,0,0.08)); }
      .balloon.b1 { animation: bob1 6.4s ease-in-out infinite; }
      .balloon.b2 { animation: bob2 5.6s ease-in-out infinite; }
      .balloon.b3 { animation: bob3 7s ease-in-out infinite; }
      .balloon.b4 { animation: bob4 6.2s ease-in-out infinite; }
      .string { opacity: 0.9; }

      @keyframes bob1 { 0% { transform: translateY(0) translateX(0) } 50% { transform: translateY(-14px) translateX(6px) } 100% { transform: translateY(0) translateX(0) } }
      @keyframes bob2 { 0% { transform: translateY(0) translateX(0) } 50% { transform: translateY(-12px) translateX(-6px) } 100% { transform: translateY(0) translateX(0) } }
      @keyframes bob3 { 0% { transform: translateY(0) translateX(0) } 50% { transform: translateY(-18px) translateX(8px) } 100% { transform: translateY(0) translateX(0) } }
      @keyframes bob4 { 0% { transform: translateY(0) translateX(0) } 50% { transform: translateY(-10px) translateX(-4px) } 100% { transform: translateY(0) translateX(0) } }

      header .backdrop-blur-md { backdrop-filter: blur(6px); }
      @media (max-width: 640px) { svg { width: 260px; height: 100px; } }
        `}</style>
        </div>
      </div>
  );
}
